      'empty-valued params count as missing (empty code is not a code)',
      () async {
        final code = server.waitForCode();
        final (status, _) = await _get('$url?code=&error=');

        expect(status, 400);
        expect(
          await code.timeout(
            const Duration(milliseconds: 100),
            onTimeout: () => 'still-pending',
          ),
          'still-pending',
        );
      },
    );

